#: Delivery-collision tie-break precedence (lower = keep this one over a higher-numbered
#: status). Ranked by how far along the pipeline the delivery is, not by pk: a SENT delivery
#: losing to a PENDING one on an arbitrary pk tie-break would silently re-announce an ad the
#: sender already delivered. String literals rather than importing AdStatus — this is a
#: historical migration and should stay isolated from the live model, same reasoning as not
#: editing 0016 to use the current model (see AD_DELIVERY_SPLIT_SPEC.md §7).
_STATUS_MERGE_PRECEDENCE = {
    "SENT": 0,
    "FAILED": 1,
    "APPROVED": 2,
    "PRICE_CHANGED": 3,
    "PENDING": 4,
    "SUPPRESSED": 5,
    "REJECTED": 6,
}


def _keep_delivery(a, b):
    """Which of two colliding deliveries for the same (ad, query) to keep. Ties within the
    same status fall back to the lower pk — deterministic and boring beats clever, matching
    the rest of this migration's philosophy.
    """
    rank_a = _STATUS_MERGE_PRECEDENCE.get(a.status, 99)
    rank_b = _STATUS_MERGE_PRECEDENCE.get(b.status, 99)
    if rank_a != rank_b:
        return a if rank_a < rank_b else b
    return a if a.pk < b.pk else b


def merge_duplicate_ads(apps, schema_editor):
    """Merge duplicate `Ad` rows sharing a (marketplace, external_id), pre-split leftovers
    from a query lacking cross-query identity (see AD_DELIVERY_SPLIT_SPEC.md §6).

    For each duplicate group: the lowest-pk row (first discovered) is canonical.
    AdDelivery/PriceChange rows on the others are repointed at it, the duplicates are then
    deleted, and the group is logged. Irreversible in substance — the merge cannot be
    undone once the duplicate rows are gone — so the reverse is a no-op (see
    `noop_reverse`), matching the precedent set by migration 0025.

    Reports via print(), not the `logging` module: migration execution order between
    independent apps isn't guaranteed, so django_db_logger's own table may not exist yet
    when this migration runs — confirmed by running this migration standalone against a
    fresh DB, where routing through `logging` broke the migration's transaction outright.
    print() goes straight to `migrate`'s stdout with no DB dependency.
    """
    Ad = apps.get_model("bazos", "Ad")
    AdDelivery = apps.get_model("bazos", "AdDelivery")
    PriceChange = apps.get_model("bazos", "PriceChange")

    duplicate_groups = (
        Ad.objects.values("marketplace", "external_id")
        .annotate(cnt=Count("id"))
        .filter(cnt__gt=1)
    )

    groups_merged = 0
    rows_deleted = 0
    delivery_collisions_resolved = 0
    groups_with_differing_price = 0

    for group in duplicate_groups:
        dupes = list(
            Ad.objects.filter(
                marketplace=group["marketplace"], external_id=group["external_id"]
            ).order_by("pk")
        )
        canonical, others = dupes[0], dupes[1:]

        if len({ad.price_raw for ad in dupes}) > 1:
            groups_with_differing_price += 1

        for dup in others:
            # A delivery collision (both duplicate rows have a delivery for the same
            # query) shouldn't happen, but the data is years old — see the bazos_id=0
            # sentinel in migration 0025 for a prior surprise of this shape. Deterministic
            # rule: keep the delivery ranked higher by _STATUS_MERGE_PRECEDENCE (falling
            # back to lower pk on a tie), not just the lower pk outright — see its docstring
            # for why raw pk order isn't safe on its own.
            for delivery in list(AdDelivery.objects.filter(ad=dup).order_by("pk")):
                collision = AdDelivery.objects.filter(ad=canonical, query_id=delivery.query_id).first()
                if collision is None:
                    delivery.ad_id = canonical.pk
                    delivery.save(update_fields=["ad"])
                    continue

                delivery_collisions_resolved += 1
                if _keep_delivery(delivery, collision) is delivery:
                    collision.delete()
                    delivery.ad_id = canonical.pk
                    delivery.save(update_fields=["ad"])
                else:
                    delivery.delete()

            PriceChange.objects.filter(ad=dup).update(ad=canonical)

            dup.delete()
            rows_deleted += 1

        groups_merged += 1

    print(
        f"Stage C Ad merge: {groups_merged} duplicate groups merged, {rows_deleted} Ad rows "
        f"deleted, {delivery_collisions_resolved} delivery collisions resolved, "
        f"{groups_with_differing_price} groups had differing price_raw across duplicates"
    )


def flush_deferred_fk_triggers(apps, schema_editor):
    """Fire the FK checks the merge above left queued, so the AddConstraint that follows can
    take its ALTER TABLE on `bazos_ad`.

    Django declares every FK on Postgres as DEFERRABLE INITIALLY DEFERRED, so deleting a
    duplicate Ad row queues an after-trigger event *on `bazos_ad`* — the RI check for the
    AdDelivery/PriceChange rows that pointed at it — which stays pending until COMMIT.
    Postgres refuses `ALTER TABLE ... ADD CONSTRAINT` on a relation with pending trigger
    events ("cannot ALTER TABLE \"bazos_ad\" because it has pending trigger events"), and a
    migration runs inside one transaction, so the AddConstraint below hits exactly that.
    `SET CONSTRAINTS ALL IMMEDIATE` runs the queued checks now and empties the queue; they
    pass, because the merge repoints every child row before deleting its parent.

    Only bites when the merge actually deleted something, which is why this got through CI
    and a duplicate-free dev DB and only surfaced against production data (v1.0.4 deploy on
    the Pi: 102 groups merged, then this ALTER TABLE aborted the whole migration).

    No-op off Postgres: SQLite has neither a deferred trigger queue nor SET CONSTRAINTS. That
    used to mean this line was unreachable from the tests, because the whole suite ran on
    SQLite — test_merge_duplicate_ads_migration.py ran this migration end to end and still
    could not have caught the bug. The suite now runs on Postgres (root conftest.py), so this
    path is genuinely covered.
    """
    if schema_editor.connection.vendor != "postgresql":
        return
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE", params=None)


